// components/pages/Activation.js - With date search
import React, { useState, useEffect } from 'react';
import { apiCall, escapeHtml } from '../../utils/api';

const Activation = ({ showToast }) => {
  const [allTills, setAllTills] = useState([]);
  const [filteredTills, setFilteredTills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchType, setSearchType] = useState('all');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const loadData = async () => {
    setLoading(true);
    const result = await apiCall('getTills');
    if (result.success) {
      setAllTills(result.tills || []);
      setFilteredTills(result.tills || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const safeToString = (value) => {
    if (value === null || value === undefined) return '';
    return String(value).toLowerCase();
  };

  const handleSearch = () => {
    const term = searchTerm.toLowerCase().trim();
    let filtered = [...allTills];

    // Filter by search term
    if (term) {
      filtered = filtered.filter(till => {
        const searchableFields = {
          name: safeToString(till.name),
          tillNumber: safeToString(till.tillNumber),
          storeNumber: safeToString(till.storeNumber),
          phone: safeToString(till.phone),
          operatorId: safeToString(till.operatorId)
        };

        if (searchType === 'all') {
          return Object.values(searchableFields).some(field => 
            field.includes(term)
          );
        }
        return searchableFields[searchType]?.includes(term) || false;
      });
    }

    // Filter by date range
    if (startDate || endDate) {
      filtered = filtered.filter(till => {
        const itemDate = till.dateCreated ? new Date(till.dateCreated) : null;
        if (!itemDate) return false;
        
        if (startDate && endDate) {
          const start = new Date(startDate);
          const end = new Date(endDate);
          end.setHours(23, 59, 59, 999);
          return itemDate >= start && itemDate <= end;
        } else if (startDate) {
          const start = new Date(startDate);
          return itemDate >= start;
        } else if (endDate) {
          const end = new Date(endDate);
          end.setHours(23, 59, 59, 999);
          return itemDate <= end;
        }
        return true;
      });
    }

    setFilteredTills(filtered);
    if (filtered.length === 0 && (term || startDate || endDate)) {
      showToast('No tills found matching your filters', true);
    }
  };

  const handleClearFilters = () => {
    setSearchTerm('');
    setSearchType('all');
    setStartDate('');
    setEndDate('');
    setFilteredTills(allTills);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const handleActivate = async (rowIndex) => {
    const pin = prompt('Enter Start PIN (4-6 digits):');
    if (pin && pin.length >= 4) {
      const res = await apiCall('activateTill', { rowIndex, startPin: pin });
      if (res.success) {
        showToast('Till activated successfully!');
        loadData();
      } else {
        showToast('Activation failed: ' + res.error, true);
      }
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading tills...
      </div>
    );
  }

  return (
    <>
      <h3 className="section-title">
        <i className="fas fa-toggle-on"></i> Till Activation
        <span className="badge-count">{filteredTills.length} tills</span>
      </h3>
      
      <div className="search-bar-advanced">
        <div className="search-row">
          <div className="search-input-group">
            <i className="fas fa-search search-icon"></i>
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Search by name, till number, store, phone, or operator..."
              className="search-input"
            />
          </div>
          <select 
            value={searchType}
            onChange={(e) => setSearchType(e.target.value)}
            className="search-select"
          >
            <option value="all">All Fields</option>
            <option value="name">Name</option>
            <option value="tillNumber">Till Number</option>
            <option value="storeNumber">Store Number</option>
            <option value="phone">Phone Number</option>
            <option value="operatorId">Operator ID</option>
          </select>
        </div>
        
        <div className="date-row">
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> From</label>
            <input 
              type="date" 
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> To</label>
            <input 
              type="date" 
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="action-group">
            <button className="btn-search-primary" onClick={handleSearch}>
              <i className="fas fa-search"></i> Apply Filters
            </button>
            <button className="btn-secondary" onClick={handleClearFilters}>
              <i className="fas fa-undo"></i> Clear
            </button>
          </div>
        </div>
      </div>

      {filteredTills.length === 0 ? (
        <div className="empty-state">
          <i className="fas fa-inbox"></i>
          <br />No tills found matching your filters
        </div>
      ) : (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Phone</th>
                <th>Till Number</th>
                <th>Store</th>
                <th>Operator</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredTills.map((till, index) => {
                const isActive = till.status === 'active';
                return (
                  <tr key={index} className={isActive ? 'active-row' : ''}>
                    <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                    <td><i className="fas fa-phone"></i> {escapeHtml(till.phone || '-')}</td>
                    <td><span className="till-badge">{escapeHtml(till.tillNumber || '-')}</span></td>
                    <td>{escapeHtml(till.storeNumber || '-')}</td>
                    <td><span className="operator-badge">{escapeHtml(till.operatorId || '-')}</span></td>
                    <td>
                      {isActive ? 
                        <span className="badge badge-success"><i className="fas fa-check-circle"></i> Active</span> : 
                        <span className="badge badge-danger"><i className="fas fa-times-circle"></i> Inactive</span>
                      }
                    </td>
                    <td>
                      {!isActive ? 
                        <button 
                          className="btn-activate" 
                          onClick={() => handleActivate(till.rowIndex)}
                        >
                          <i className="fas fa-play"></i> Activate
                        </button> : 
                        <span className="badge badge-success">Activated ✓</span>
                      }
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
};

export default Activation;
